@media(max-width:700px){.game-shell{padding:0 12px}.topbar{height:54px}.season{font-size:8px;letter-spacing:.5px}.brand{font-size:12px}.brand-mark{width:27px;height:27px}.intro-row{padding:19px 0 15px}h1{font-size:31px}.subtitle{font-size:11px}.match-status{gap:7px}.status-pill{font-size:8px;padding:6px}.arena-layout{display:flex;flex-direction:column;gap:10px}.playfield-wrap{order:0;padding:9px 10px 9px}.player-panel{order:1;min-height:0;padding:12px}.right-panel{display:none}.opponent-bar{height:42px;padding-bottom:8px;gap:8px}.opponent-id{min-width:137px}.opponent-id b{font-size:9px}.opponent-id small{font-size:7px}.enemy-status{font-size:7px;padding:4px}.boards-row{gap:13px;padding-top:10px}.board-column{width:min(57vw,270px);max-width:unset}.main-frame{height:auto;aspect-ratio:1/2}.opponent-column{width:min(29vw,140px)}.opponent-column .board-frame{height:auto;aspect-ratio:1/2}.board-topline{font-size:7px;height:16px}.board-footer{font-size:7px}.enemy-next-wrap{height:72px;margin-top:8px;padding:6px}.enemy-next-wrap canvas{height:45px}.enemy-attack{font-size:7px;padding:6px 1px}.arena-feed{height:30px;margin-top:10px;font-size:8px}.enemy-health{min-width:58px}.board-overlay .overlay-card{padding:10px}.overlay-sigil{font-size:25px}.overlay-card b{font-size:14px}.overlay-card p{font-size:9px;margin:6px 0 12px}.primary-button{padding:9px;font-size:8px}.player-panel{display:grid;grid-template-columns:1fr 1fr;column-gap:12px;align-items:center}.player-panel .identity,.player-panel .xp-wrap{grid-column:span 1}.player-panel .xp-wrap{margin:0}.player-panel .stat-grid{grid-column:1 / -1;grid-row:2;grid-template-columns:repeat(4,1fr);margin-top:10px}.player-panel .stat{padding:7px 6px}.stat-label{font-size:7px}.stat strong{font-size:12px}.player-panel .side-divider,.player-panel .panel-heading,.player-panel .spell-list,.player-panel .spell-hint{grid-column:1/-1}.player-panel .side-divider{margin:11px 0}.player-panel .panel-heading{margin-bottom:0}.player-panel .spell-list{grid-template-columns:repeat(3,1fr);gap:5px;margin-top:7px}.spell-card{height:58px;padding:5px;gap:3px;display:grid;grid-template-columns:20px 1fr 16px}.spell-icon{font-size:16px;width:20px}.spell-copy{gap:3px}.spell-copy b{font-size:8px}.spell-copy small{font-size:7px;line-height:1.2}.spell-card kbd{font-size:7px;padding:2px}.spell-cost{right:4px;bottom:2px;font-size:7px}.spell-hint{font-size:8px;margin-top:7px}.touch-controls{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:10px 0}.touch-row{display:grid;grid-template-columns:repeat(3,1fr);gap:6px}.touch-row button{height:42px;border:1px solid #344054;border-radius:7px;background:#151d2b;color:#d5deed;font:18px 'DM Mono',monospace;touch-action:manipulation}.touch-row button:active{background:#30394a}.touch-row .drop-touch,.touch-row button[data-action=hold]{font-size:10px;font-weight:700}.page-footer{font-size:7px;padding:8px 2px 12px}}
