function block(ctx,x,y,size,color,ghost=false){const pad=Math.max(1,size*.055),px=x*size+pad,py=y*size+pad,w=size-pad*2,h=size-pad*2;ctx.globalAlpha=ghost?.28:1;ctx.fillStyle=color;ctx.fillRect(px,py,w,h);if(!ghost){ctx.fillStyle='rgba(255,255,255,.25)';ctx.fillRect(px,py,w,Math.max(1,size*.08));ctx.fillRect(px,py,Math.max(1,size*.08),h);ctx.fillStyle='rgba(0,0,0,.24)';ctx.fillRect(px,py+h-Math.max(1,size*.08),w,Math.max(1,size*.08));ctx.fillRect(px+w-Math.max(1,size*.08),py,Math.max(1,size*.08),h);ctx.fillStyle='rgba(255,255,255,.10)';ctx.fillRect(px+size*.22,py+size*.22,w*.42,h*.16)}ctx.globalAlpha=1;}
function drawBoard(ctx,canvas,board,piece,enemy=false){const w=canvas.width,h=canvas.height,size=w/COLS;ctx.clearRect(0,0,w,h);ctx.fillStyle='#0a0f1b';ctx.fillRect(0,0,w,h);ctx.strokeStyle=enemy?'rgba(130,92,111,.09)':'rgba(107,132,165,.10)';ctx.lineWidth=1;for(let x=0;x<=COLS;x++){ctx.beginPath();ctx.moveTo(x*size+.5,0);ctx.lineTo(x*size+.5,h);ctx.stroke()}for(let y=0;y<=ROWS;y++){ctx.beginPath();ctx.moveTo(0,y*size+.5);ctx.lineTo(w,y*size+.5);ctx.stroke()}
  for(let y=0;y<ROWS;y++)for(let x=0;x<COLS;x++)if(board[y][x])block(ctx,x,y,size,board[y][x]);if(piece){let ghostY=piece.y;while(!collides(board,piece,0,ghostY-piece.y+1))ghostY++;if(ghostY!==piece.y)for(let y=0;y<piece.m.length;y++)for(let x=0;x<piece.m[y].length;x++)if(piece.m[y][x]&&ghostY+y>=0)block(ctx,piece.x+x,ghostY+y,size,SHAPES[piece.type].color,true);for(let y=0;y<piece.m.length;y++)for(let x=0;x<piece.m[y].length;x++)if(piece.m[y][x]&&piece.y+y>=0)block(ctx,piece.x+x,piece.y+y,size,SHAPES[piece.type].color);}}
function renderMini(canvas,type){const ctx=canvas.getContext('2d'),w=canvas.width,h=canvas.height;ctx.clearRect(0,0,w,h);if(!type)return;const m=SHAPES[type].matrix;let minX=99,maxX=-1,minY=99,maxY=-1;for(let y=0;y<m.length;y++)for(let x=0;x<m[y].length;x++)if(m[y][x]){minX=Math.min(minX,x);maxX=Math.max(maxX,x);minY=Math.min(minY,y);maxY=Math.max(maxY,y)}const cell=Math.min(22,w/(maxX-minX+1),h/(maxY-minY+1)),ox=(w-(maxX-minX+1)*cell)/2,oy=(h-(maxY-minY+1)*cell)/2;for(let y=minY;y<=maxY;y++)for(let x=minX;x<=maxX;x++)if(m[y][x]){const xx=ox+(x-minX)*cell,yy=oy+(y-minY)*cell;ctx.fillStyle=SHAPES[type].color;ctx.fillRect(xx+1,yy+1,cell-2,cell-2);ctx.fillStyle='rgba(255,255,255,.25)';ctx.fillRect(xx+2,yy+2,cell-4,2)}}
function renderPreviews(){renderMini($('#nextPiece'),state.queue[0]);renderMini($('#holdPiece'),state.hold);renderMini($('#enemyNext'),nextTypePreview);}
